CalculatorElement.MainFunction:
{
;default background is D50 for relative white point
env(bkgX) not if {pop 0.9642}
env(bkgY) not if {pop 1.000000}
env(bkgZ) not if {pop 0.8249}
1 in(4) sub tput(0)
tget(0) 0 gt if {
  tget(0) tint(0) mul(3)
  tget(0) tint(1) add(3)
}
in(0,4) 
curv(2) copy(4) tput(0,4)
clut(3) mul(3)
tget(0,4)
clut(4) add(3) 
out(0,3)
}
